entries[200063] = { ["name"] = "Observant Riddle \"Treat\"", ["text"] = "Quest Item\nUse: Throw the \"treat\" at the Possessive Hornswog.\n\"A dubiously-crafted morsel for a cantankerous hornswog.\"" }
entries[200064] = { ["name"] = "Marmoni's Prize", ["text"] = "Binds when picked up\nUnique\nUse: Combine the riddle ingredients into a dubious \"treat\".\nRequires level 10 to 70 ( 70)\n\"A shimmery yellow banana ferreted away for safekeeping.\"" }
entries[200065] = { ["name"] = "Adventurer's Lost Soap Bar", ["text"] = "Binds when picked up\nUnique\nUse: Combine the riddle ingredients into a dubious \"treat\".\nRequires level 10 to 70 ( 70)\n\"A necessary item long forgotten by a hapless adventurer.\"" }
entries[200066] = { ["name"] = "Well-Preserved Bone", ["text"] = "Binds when picked up\nUnique\nUse: Combine the riddle ingredients into a dubious \"treat\".\nRequires level 10 to 70 ( 70)\n\"A dry, crusty piece of bone long protected from the elements.\"" }
entries[200067] = { ["name"] = "Whispering Shard", ["text"] = "Quest Item\n\"This shard whispers many compliments into your mind. You are pretty great, aren't you?\"" }
entries[200069] = { ["name"] = "Obsidian Cache", ["text"] = "Binds when picked up\n\"Contains gold, Dragon Isles Supplies, rare Dragon Isles Artifacts and Titan Relics as well as a chance for cosmetic Djaradin weapons and armor.\"\n<Right Click to Open>" }
entries[200070] = { ["name"] = "Obsidian Strongbox", ["text"] = "Binds when picked up\n\"Contains gold, Dragon Isles Supplies, rare artifacts and relics as well as a chance for cosmetic Djaradin weapons and armor.\"\n<Right Click to Open>" }
entries[200071] = { ["name"] = "Sacred Tuskarr Totem", ["text"] = "Binds when picked up\n\"Stolen from the Iskaara Tuskarr, Elder Poa would reward you if you returned it to them.\"" }
entries[200072] = { ["name"] = "Dragonbane Keep Strongbox", ["text"] = "Binds when picked up\n\"Contains plundered items, supplies, gold and artifacts.\"\n<Right Click to Open>" }
entries[200073] = { ["name"] = "Valdrakken Treasures", ["text"] = "Binds when picked up\nUnique\n\"Contains equipment, supplies, and treasures gathered throughout the ages.\"\n<Right Click to Open>" }
entries[200074] = { ["name"] = "Frosted Rimefin Tuna", ["text"] = "Use: Brush off the ice coating this fish.\nCrafting Reagent\n\"A sturdy fish coated in a frosted outer shell.\"\nSell Price:" }
entries[200075] = { ["name"] = "Flying Fish Bones", ["text"] = "Iskaaran Fishing Gear Material\nBinds when picked up\nUnique\n\"Should be plentiful in fishing villages, such as Iskaara. Bring this to Tavio.\"" }
entries[200076] = { ["name"] = "Harpoon Head", ["text"] = "Iskaaran Fishing Gear Material\nBinds when picked up\nUnique\n\"Skilled blacksmiths, such as Iskaara Tuskarr, should have one. Bring it to Tavio in Iskaara.\"" }
entries[200077] = { ["name"] = "Wooden Pole", ["text"] = "Iskaaran Fishing Gear Material\nBinds when picked up\nUnique\n\"Should be easy to find somewhere in the forests of western Azure Span. Bring to Tavio in Iskaara.\"" }
entries[200078] = { ["name"] = "Pickaxe Blade", ["text"] = "Iskaaran Fishing Gear Material\nBinds when picked up\nUnique\n\"You could probably \"borrow\" one in a Dragonscale Expedition camp, such as Three-Falls Lookout. Bring it to Tavio in Iskaara.\"" }
entries[200079] = { ["name"] = "Sea-Polished Basalt", ["text"] = "Iskaaran Fishing Gear Material\nBinds when picked up\nUnique (3)\n\"Should be abundant where lava meets the sea, such as Wild Coast. Bring to Tavio in Iskaara.\"" }
entries[200080] = { ["name"] = "Draconium Nugget", ["text"] = "Iskaaran Fishing Gear Material\nBinds to Warband\n\"Used to improve Iskaaran fishing net. Bring to Tavio in Iskaara. Can be fished in Dragon Isles highlands, ice holes, or lava pools.\"" }
entries[200081] = { ["name"] = "Strong Seavine", ["text"] = "Iskaaran Fishing Gear Material\nBinds to Warband\n\"Used to improve Iskaaran harpoon. Bring to Tavio in Iskaara. Can be fished in Dragon Isles highlands, ice holes, or lava pools.\"" }
entries[200082] = { ["name"] = "Battered Imbu-made Net", ["text"] = "Iskaaran Fishing Gear Material\nBinds to Warband\n\"Used to improve Iskaaran fishing net. Bring to Tavio in Iskaara. Can be fished in Dragon Isles highlands, ice holes, or lava pools.\"" }
