entries[200084] = { ["name"] = "Salinated Serevite", ["text"] = "Iskaaran Fishing Gear Material\nBinds to Warband\n\"Used to improve Iskaaran harpoon. Bring to Tavio in Iskaara. Can be fished in Dragon Isles highlands, ice holes, or lava pools.\"" }
