entries[200114] = { ["name"] = "Stormie", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)\nSell Price:" }
entries[200115] = { ["name"] = "Sarantuya the Ever-True", ["text"] = "Quest Item\n\"By moonlight, assassins were sent for Maruuk. By moonlight, Teera slayed them first.\"" }
entries[200116] = { ["name"] = "Everlasting Horn of Lavaswimming", ["text"] = "Binds when picked up\nToy\nUse: Drink from this horn to become immune to lava outdoors in the Dragon Isles for 10 minutes. (30 Min Cooldown)\n\"Just don't be swimming when it wears off.\"" }
entries[200117] = { ["name"] = "Watcher's Golden Girdle", ["text"] = "Quest Item\nUnique\n\"Holds many potential secrets of the Titans, metalworking, and most importantly... fashion.\"" }
entries[200118] = { ["name"] = "Yellow Scouting Ottuk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 25 with the Iskaara Tuskarr.\n\n\"The yellow scouting ottuk love to hide and they blend in well to their surroundings. When not 'playing' hide and seek with their riders, they are perfect companions when scouting enemy encampments.\"\nFaction:\nIskaara Tuskarr\nRenown:\n25\nVendor:\nTatto\nLocation:\nIskaara\nCost:\n2\n2\n750" }
entries[200119] = { ["name"] = "Everblazing Fireheart", ["text"] = "Quest Item\nUnique\n\"They say that Firava's heart grew three sizes that day, thanks to the Primalists.\"" }
entries[200120] = { ["name"] = "Irideus' Power Core", ["text"] = "Quest Item\nUse: Attune the Power Core to an elite titanic denizen of Tyrhold, weakening it.\n\"Taken from the Halls of Infusion, this device once powered up Watcher Irideus. Now it must be attuned again to regain its original power output.\"" }
entries[200121] = { ["name"] = "Potion of Beginner's Luck", ["text"] = "Use: +1 Luck\n\"You can do it!\"" }
entries[200122] = { ["name"] = "Temporal Spyglass", ["text"] = "Quest Item\nUnique\n\"Flickers of things past, present, and future overlap as you look through it.\"" }
