entries[200542] = { ["name"] = "Breezy Companion", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 Intellect\nEquip: A small breeze follows you around, periodically healing or shielding you or your allies for 16409 .\nSell Price:" }
