entries[200544] = { ["name"] = "Mistvale Map: Illegible", ["text"] = "Quest Item\n\"A detailed map of Valdrakken, but the city has been scribbled over. There are notes scrawled in the margins. There's also a dire warning written on the back.\"\n<Right Click to Read>" }
