entries[200548] = { ["name"] = "Maldra's Manacles Key", ["text"] = "Quest Item\n\"Orian Darkwater shackled Maldra. This key could free her.\"" }
entries[200549] = { ["name"] = "Restored Titan Artifact", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 Intellect\nUse: Shield an ally for up to 37740 from a great distance and gain up to 5726 Speed. The Absorb and Speed amounts vary depending on the distance between you and your target, with the Absorb increasing and the Speed decreasing the closer you are. (1 Min Cooldown)\nSell Price:" }
entries[200550] = { ["name"] = "Very Comfortable Pelt", ["text"] = "Binds when picked up\nToy\nUse: Lounge around, Maruuk style! (20 Min Cooldown)\nRequires Renown 3 with the Maruuk Centaur and completing the quest \"Cultural Exchange\".\nSell Price:" }
entries[200551] = { ["name"] = "Comfortable Pile of Pelts", ["text"] = "Binds when picked up\nToy\nUse: Rest like a khanam wherever you go! (20 Min Cooldown)\nRequires Renown 3 with the Maruuk Centaur and completing the quest \"Cultural Exchange\".\nSell Price:" }
entries[200552] = { ["name"] = "Torrent Caller's Shell", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 Strength\nUse: Channel torrents around you dealing [ 1906 * (6) * (1 + Versatility)] nature damage to nearby enemies over 3 sec. Then unleash a powerful blast dealing 53355 nature damage split between all nearby enemies. (2 Min, 30 Sec Cooldown)\nSell Price:" }
entries[200553] = { ["name"] = "Panthis Nectar", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Panthis Nectar to your Dragon Isles Supplies.\n\"The bowl-shaped flower creates a well for nectar to pool. High in sugars, the nectar is highly desired when refined for cooking.\"\nSell Price:" }
entries[200554] = { ["name"] = "Dropcap Head", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Oily Dropcap Head to your Dragon Isles Supplies.\n\"The drop cap leaks an oil when it matures, this oil is highly prized as a fire accelerant.\"\nSell Price:" }
entries[200555] = { ["name"] = "Inferno Seeds", ["text"] = "Dragon Isles Supplies\nBinds when picked up\nAdd the Inferno Seeds to your Dragon Isles Supplies.\n\"Akin to a gunpowder, the Inferno Pods explode when fully mature spreading the seeds. The Djaradin gather them when they are just flowering and use them to get their forges to near molten temperatures.\"\nSell Price:" }
entries[200556] = { ["name"] = "Enchanted Arcana Vessel", ["text"] = "Quest Item\nUnique\n\"Wisps of arcane magic swirl within the enchanted vessel.\"" }
