entries[200559] = { ["name"] = "Cobalt Duelist's Saber", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Sword\n1 Damage Speed 2.60\n(0.4 damage per second)\nRequires the Cobalt Assembly power to be at Maximum.\nUse: Add this appearance to your Warband collection.\nSell Price:" }
