entries[200563] = { ["name"] = "Primal Ritual Shell", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 [Agility or Strength or Intellect]\nUse: Perform the summoning ritual and commune with one of the Primal Turtles to gain its blessing.\n\nThe ritual site can be found south of Uktulut Pier in The Waking Shores, near the remains of a dragon.\nSell Price:" }
